const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=18)=>{const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',test:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6M9 13h6M9 17h3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3zM20 2v4m-2-2h4"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8v-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M8 15h2m4 0h2M8 18h2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',down:'<path d="m7 10 5 5 5-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',logout:'<path d="M9 4H4v16h5m5-13 5 5-5 5m-6-5h11"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3z"/><path d="m8 12 3 3 5-6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',school:'<path d="m2 9 10-6 10 6-10 6-10-6zM6 12v6c4 3 8 3 12 0v-6m4-3v9"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',flag:'<path d="M5 21V3c4-3 9 3 14 0v10c-5 3-10-3-14 0"/>',folder:'<path d="M3 7V4h6l3 3h9v13H3V7z"/>',edit:'<path d="m14 5 5 5M4 20l4-1L21 6l-5-5L3 14l1 6z"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`};
const art=`<svg class="hero-art" viewBox="0 0 300 170" fill="none" aria-hidden="true"><path d="M0 130h60c55 0 25-100 85-100h155M0 100h50c65 0 40-40 85-40h165M0 155h80c60 0 40-65 90-65h130" stroke="#6b9270" stroke-width="1"/><path d="M20 130h40c55 0 25-100 85-100h155" stroke="#c8e494" stroke-width="2.5" stroke-dasharray="5 6"/><circle cx="61" cy="130" r="13" fill="#315b45" stroke="#91b371"/><path d="m55 130 4 4 8-9" stroke="#d3e99b" stroke-width="2"/><circle cx="146" cy="30" r="18" fill="#d7eb9e"/><path d="m139 30 5 5 9-10" stroke="#31513e" stroke-width="2"/><circle cx="224" cy="60" r="12" fill="#345f48" stroke="#9fbd79"/><circle cx="224" cy="60" r="4" fill="#d3e99b"/><circle cx="176" cy="90" r="8" fill="#335c43" stroke="#8fb06d"/><circle cx="275" cy="30" r="6" fill="#d7eb9e"/><path d="M75 15v8m-4-4h8M242 113v12m-6-6h12M118 142v8m-4-4h8" stroke="#6d9570"/></svg>`;
const state={token:sessionStorage.getItem('learnpath.token'),user:null,ctx:null,subject:0,section:0,page:'overview',data:{},revision:0,tab:'departments',filter:'all',attempt:null,timer:null};
const titles={overview:'Overview',students:'Student insights',tests:'Assessments',questions:'Question bank',assignments:'Assignments',attendance:'Attendance',plans:'Study plans',coach:'AI study coach',gaps:'Learning gaps',catalog:'Academic setup',users:'People & roles',calendar:'Academic calendar',showcase:'Project showcase',assessment:'Take assessment'};
const names={overview:'grid',students:'users',tests:'test',questions:'book',assignments:'folder',attendance:'calendar',plans:'target',coach:'spark',gaps:'chart',catalog:'school',users:'users',calendar:'calendar',showcase:'spark'};
const fmt=v=>v==null?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:1});
const date=v=>!v?'Not scheduled':new Date(v+(v.includes('T')&&!/[Z+]\d*$/.test(v)?'Z':v.includes('T')?'':'T00:00:00')).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const initials=s=>(s||'?').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const person=(name,sub='')=>`<div class="person"><span class="avatar">${E(initials(name))}</span><div><strong>${E(name)}</strong><small>${E(sub)}</small></div></div>`;
const badge=(text,color='')=>`<span class="badge ${color}">${E(String(text||'Unknown').replaceAll('_',' '))}</span>`;
const btn=(text,action,style='',data='')=>`<button class="btn ${style}" data-action="${action}" ${data}>${text}</button>`;
const empty=(text,detail='',action='')=>`<div class="empty">${icon('book',28)}<h3>${E(text)}</h3><p>${E(detail)}</p>${action}</div>`;
const panel=(title,subtitle,body,extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra}</div><div class="panel-body">${body}</div></section>`;
const table=(heads,rows)=>rows.length?`<div class="table-scroll"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Nothing here yet','Records will appear here as you use the project.');
const option=(id,text,selected=false)=>`<option value="${E(id)}" ${selected?'selected':''}>${E(text)}</option>`;
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
const selectField=(label,name,options,extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${options}</select></label>`;
const area=(label,name,value='',extra='')=>`<label class="field full">${label}<textarea name="${name}" ${extra}>${E(value)}</textarea></label>`;
const subject=()=>state.ctx?.subjects.find(s=>s.subject_id===state.subject);
const staff=()=>state.user?.role!=='STUDENT';
const admin=()=>state.user?.role==='ADMIN';
const query=()=>`subject_id=${state.subject}&section_id=${state.section}`;
const topicOptions=()=>state.ctx.topics.filter(t=>t.subject_id===state.subject).map(t=>option(t.topic_id,t.topic_name)).join('');
const studentOptions=()=>staff()?(state.data.dashboard?.students||[]).map(s=>option(s.student_id,s.full_name)).join(''):option(state.user.user_id,state.user.full_name);
const avg=values=>{const good=values.filter(v=>v!=null);return good.length?good.reduce((a,b)=>a+Number(b),0)/good.length:null};
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show ${error?'error':''}`;clearTimeout(state.toast);state.toast=setTimeout(()=>t.className='',5500)}
async function api(path,method='GET',body){const headers={};if(state.token)headers.Authorization='Bearer '+state.token;if(body!==undefined)headers['Content-Type']='application/json';let r;try{r=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)})}catch{throw Error('Cannot reach the backend. Start the project and try again.')}const data=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&path!=='/auth/login'){logout();throw Error('Your session expired. Please sign in again.')}let message=data.detail;if(Array.isArray(message))message=message.map(e=>`${e.loc.slice(1).join(' ')}: ${e.msg}`).join('; ');throw Error(typeof message==='string'?message:'The request could not be completed.')}return data}
async function action(fn,button){if(button)button.disabled=true;try{await fn()}catch(e){toast(e.message,true)}finally{if(button?.isConnected)button.disabled=false}}
function modal(title,content,onSubmit,submit='Save changes'){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${E(title)}</h2><button class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${onSubmit?'<form id="modal-form"><div class="error-box" role="alert"></div>':''}${content}${onSubmit?`<div class="form-actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">${E(submit)}</button></div></form>`:''}</div>`;$$('[data-close]',d).forEach(b=>b.onclick=()=>d.close());if(onSubmit)$('#modal-form',d).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f);b.disabled=true;try{await onSubmit(new FormData(f),f);d.close()}catch(err){$('.error-box',f).textContent=err.message}finally{b.disabled=false}};d.showModal()}
function logout(){sessionStorage.removeItem('learnpath.token');state.token=null;state.user=null;state.ctx=null;state.attempt=null;clearInterval(state.timer);$('#modal').close();loginScreen()}
function loginScreen(){document.title='Sign in · LearnPath AI';$('#app').innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="brand-mark">L</span>LearnPath<em>AI</em></div><div class="story-main"><div class="eyebrow">A little insight. A big difference.</div><h1>Every learner.<br>A <span>clearer path.</span></h1><p>Turn assessments into understanding, and understanding into a plan to move forward.</p>${art.replace('hero-art','path-art')}<div class="meta-row" style="color:#a8c098">${icon('shield',15)} Built for engineering education</div></div><div class="story-footer"><span>NEURAL CODE NINJAS / NCN–02</span><span>Learn. Reflect. Grow.</span></div></section><section class="login-form-wrap"><div class="login-form"><div class="eyebrow">YOUR LEARNING WORKSPACE</div><h2>Welcome back.</h2><p>Sign in to see the bigger picture of learning.</p><form id="login-form"><div id="login-error" class="error-box" role="alert"></div>${field('Email address','email','email','','placeholder="you@college.edu" autocomplete="username" required')}${field('Password','password','password','','placeholder="Enter your password" autocomplete="current-password" required')}<button class="btn primary" type="submit">Sign in to workspace ${icon('arrow',16)}</button></form><div class="login-demo"><p>EXPLORE THE LOCAL SHOWCASE · FICTIONAL ACCOUNTS</p><div class="demo-roles">${['Admin','Faculty','HOD','Student'].map(r=>`<button type="button" data-demo="${r}">${r}</button>`).join('')}</div><p style="margin:12px 0 0;font-size:10px">Choose a role to explore the connected project with synthetic data.</p></div><div class="login-legal">Your college data, connected in one place.<br>FastAPI + MySQL · Local project showcase</div></div></section></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.currentTarget);b.disabled=true;$('#login-error').textContent='';try{const f=new FormData(e.currentTarget);await signIn(f.get('email'),f.get('password'))}catch(err){if($('#login-error'))$('#login-error').textContent=err.message}finally{b.disabled=false}};$$('[data-demo]').forEach(b=>b.onclick=()=>action(async()=>{const emails={Admin:'admin.demo@example.com',Faculty:'faculty.demo@example.com',HOD:'hod.demo@example.com',Student:'mira.demo@example.com'};const form=$('#login-form');form.elements.namedItem('email').value=emails[b.dataset.demo];form.elements.namedItem('password').value='';form.elements.namedItem('password').focus()},b))}
async function signIn(email,password){const auth=await api('/auth/login','POST',{email,password});state.token=auth.access_token;sessionStorage.setItem('learnpath.token',state.token);location.hash='overview';await initialize()}
async function initialize(){state.ctx=await api('/ui/context');state.user=state.ctx.user;const scopes=state.ctx.scopes;const previous=sessionStorage.getItem('learnpath.scope');const pair=scopes.find(s=>`${s.subject_id}:${s.section_id}`===previous)||scopes[0];state.subject=pair?.subject_id||0;state.section=pair?.section_id||0;shell();await navigate()}
function shell(){const u=state.user;const nav=['overview',...(staff()?['students']:[]),'tests',...(staff()?['questions']:[]),'assignments','attendance','plans','coach',...(['ADMIN','HOD'].includes(u.role)?['gaps']:[]),...(staff()?['catalog']:[]),...(admin()?['users']:[]),'calendar','showcase'];$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">L</span>LearnPath<em>AI</em></div><div class="workspace-tag"><span class="school">${icon('school',18)}</span><div><strong>Engineering workspace</strong><small>Academic year 2026–27</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(n=>`<a href="#${n}" data-nav="${n}">${icon(names[n])}<span>${E(titles[n])}</span>${n==='coach'?'<span class="nav-count">AI</span>':''}</a>`).join('')}</nav><div class="side-bottom"><div class="side-card">${icon('spark',20)}<h4 style="margin-top:9px">Small steps. Real progress.</h4><p>A personalized plan turns learning gaps into your next steps.</p><a href="#plans">Explore study plans ${icon('arrow',13)}</a></div><div class="side-profile"><span class="avatar">${E(initials(u.full_name))}</span><div><strong>${E(u.full_name.replace('Demo ','').replace('Local ',''))}</strong><small>${E(u.role.toLowerCase())} workspace</small></div><button class="icon-btn" data-action="logout" aria-label="Sign out" title="Sign out">${icon('logout',16)}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>Workspace <span>/</span><strong id="breadcrumb">Overview</strong></div><div class="top-actions"><span class="live-dot">Connected workspace</span><span class="divider"></span><span class="top-date">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span><button class="icon-btn" data-action="refresh" aria-label="Refresh data" title="Refresh data">${icon('refresh',16)}</button><span class="avatar" style="height:29px;width:29px;font-size:9px">${E(initials(u.full_name))}</span></div></header><div class="content"><div id="page-heading"></div><div id="scope"></div><div id="view"></div><footer class="footer"><span>LearnPath AI · Built for better learning outcomes.</span><span>Neural Code Ninjas &nbsp; / &nbsp; <a href="/docs" target="_blank" rel="noopener">API documentation ↗</a></span></footer></div></main>`;document.onclick=event=>{const b=event.target.closest('[data-action]');if(b)action(()=>dispatch(b.dataset.action,b),b);const a=event.target.closest('[data-nav]');if(a){$('.sidebar')?.classList.remove('open');if(state.attempt&&state.page==='assessment'&&!confirm('Leave the test screen? Your current answers will stay saved in this browser.'))event.preventDefault()}}}
function renderScope(){const c=state.ctx;const allowed=new Set(c.scopes.map(s=>s.subject_id));$('#scope').innerHTML=`<div class="scope-bar"><label for="subject-select">Viewing</label><select id="subject-select" aria-label="Subject">${c.subjects.filter(s=>allowed.has(s.subject_id)).map(s=>option(s.subject_id,s.subject_name,s.subject_id===state.subject)).join('')}</select><select id="section-select" aria-label="Section">${c.sections.filter(s=>c.scopes.some(p=>p.subject_id===state.subject&&p.section_id===s.section_id)).map(s=>option(s.section_id,`Section ${s.section_name} · ${s.academic_year}`,s.section_id===state.section)).join('')}</select><span class="scope-note">${icon('shield',12)} Synthetic showcase data · Live from MySQL</span></div>`;$('#subject-select').onchange=e=>{state.subject=Number(e.target.value);state.section=c.scopes.find(s=>s.subject_id===state.subject)?.section_id||0;scopeChanged()};$('#section-select').onchange=e=>{state.section=Number(e.target.value);scopeChanged()}}
function scopeChanged(){sessionStorage.setItem('learnpath.scope',`${state.subject}:${state.section}`);state.filter='all';navigate()}
function heading(){const descriptions={overview:staff()?'Your learning community, at a glance.':'Your progress, your next steps, your potential.',students:'Understand the story behind every score.',tests:'Meaningful assessments. Actionable understanding.',questions:'A thoughtful question is where learning begins.',assignments:'Keep coursework, submissions and feedback together.',attendance:'Connect classroom participation with learning progress.',plans:'Turn learning gaps into small, achievable steps.',coach:'A little guidance when a concept needs another explanation.',gaps:'See where your department can make the biggest difference.',catalog:'Build the academic structure behind your workspace.',users:'The people and roles that make learning happen.',calendar:'Keep important academic dates in view.',showcase:'One connected journey, from assessment to improvement.',assessment:'Take your time, think it through, and do your best.'};$('#page-heading').innerHTML=`<div class="page-heading"><div><div class="eyebrow">${state.page==='overview'?`HELLO, ${E(state.user.full_name.replace('Demo ','').split(' ')[0].toUpperCase())}`:'LEARNPATH / '+E(state.page.toUpperCase())}</div><h1>${state.page==='overview'?'A clearer picture of learning.':E(titles[state.page]||'Workspace')}</h1><p>${E(descriptions[state.page]||'')}</p></div><div class="actions">${state.page==='overview'?btn(icon('download',14)+' Export report','export'):''}${({tests:staff()?btn(icon('plus',14)+' Create assessment','create-test','primary'):'',questions:btn(icon('plus',14)+' Add question','create-question','primary'),assignments:staff()?btn(icon('plus',14)+' New assignment','create-assignment','primary'):'',plans:btn(icon('spark',14)+' Build a study plan','create-plan','primary'),users:btn(icon('plus',14)+' Add person','create-user','primary'),calendar:admin()?btn(icon('plus',14)+' Add event','create-event','primary'):''})[state.page]||''}</div></div>`}
async function navigate(){if(!state.user)return;let page=location.hash.slice(1).split('?')[0]||'overview';if(!titles[page])page='overview';state.page=page;const rev=++state.revision;document.title=`${titles[page]} · LearnPath AI`;$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('#breadcrumb').textContent=titles[page];heading();renderScope();$('#scope').hidden=['catalog','users','calendar','showcase','assessment'].includes(page);$('#view').innerHTML='<div class="loading"><span class="spinner"></span>Connecting the dots…</div>';clearInterval(state.timer);try{if(page==='assessment'){await assessment();return}if(!state.subject&&!['catalog','users','calendar','showcase'].includes(page)){$('#view').innerHTML=empty('Your workspace is ready for a new chapter','Ask an administrator to map your enrollment or teaching assignment.');return}const data={};if(['overview','students','tests','assignments','attendance','plans'].includes(page)){const [tests,attempts,assignments]=await Promise.all([api('/tests?'+query()),api('/ui/attempts?'+query()),api('/assignments?'+query())]);Object.assign(data,{tests,attempts,assignments});if(staff())data.dashboard=await api('/dashboard?'+query());else data.performance=await api(`/students/${state.user.user_id}/performance?subject_id=${state.subject}`)}if(page==='assignments'&&!staff()){data.submissions=Object.fromEntries(await Promise.all(data.assignments.map(async a=>[a.assignment_id,(await api(`/assignments/${a.assignment_id}/submissions`))[0]||null])))}if(page==='questions')data.questions=await api(`/questions?subject_id=${state.subject}&limit=200`);if(page==='attendance')data.attendance=await api('/ui/attendance?'+query());if(page==='users')data.users=await api('/users?limit=200');if(page==='gaps'){const d=state.user.department_id||state.ctx.departments[0]?.department_id;data.gaps=d?await api(`/departments/${d}/learning-gaps`):[]}if(rev!==state.revision)return;state.data=data;const renderers={overview,students,tests,questions,assignments,attendance,plans,coach,gaps,catalog,users,calendar,showcase};await renderers[page]();}catch(e){if(rev===state.revision&&state.user)$('#view').innerHTML=`<div class="error-page"><h2>We couldn’t load this view.</h2><p>${E(e.message)}</p>${btn('Try again','refresh','primary')}</div>`}}
window.addEventListener('hashchange',()=>navigate());
function stat(label,value,note,type='chart'){return `<section class="stat"><div class="stat-top">${E(label)}<span class="stat-icon">${icon(type,15)}</span></div><div class="stat-number">${value}</div><div class="stat-foot">${note}</div></section>`}
function chart(students){return `<div class="chart"><div class="chart-lines">${[100,75,50,25,0].map(v=>`<span><small>${v}%</small></span>`).join('')}</div><div class="chart-bars">${students.slice(0,8).map(s=>`<div class="bar-group"><div class="bar" style="height:${Math.max(0,Math.min(100,s.average_score||0))}%" title="${E(s.full_name)} · Score ${fmt(s.average_score)}%"></div><div class="bar light" style="height:${Math.max(0,Math.min(100,s.attendance_percent||0))}%" title="${E(s.full_name)} · Attendance ${fmt(s.attendance_percent)}%"></div><small>${E(s.full_name.replace(' Demo Student',''))}</small></div>`).join('')}</div></div>`}
function studentRows(list){return list.map(s=>[person(s.full_name,'Student'),`<div class="score-line">${fmt(s.average_score)}${s.average_score!=null?'%':''}<span class="track ${s.average_score<40?'orange':''}"><span style="width:${s.average_score||0}%"></span></span></div>`,`${fmt(s.attendance_percent)}${s.attendance_percent!=null?'%':''}`,badge(s.needs_attention?'Needs attention':'On track',s.needs_attention?'orange':'green'),`<button class="text-btn" data-action="student-detail" data-id="${s.student_id}">View insights ${icon('arrow',12)}</button>`])}
function overview(){const d=state.data;const learners=staff()?d.dashboard.students:[{...d.performance,full_name:state.user.full_name,student_id:state.user.user_id,needs_attention:(d.performance.average_score!=null&&d.performance.average_score<40)||(d.performance.attendance_percent!=null&&d.performance.attendance_percent<60)}];const attention=learners.filter(s=>s.needs_attention).length,score=avg(learners.map(s=>s.average_score)),att=avg(learners.map(s=>s.attendance_percent));const latest=d.tests.slice(-3).reverse();const items=d.assignments.slice(0,3);$('#view').innerHTML=`<section class="hero"><div><div class="eyebrow">INSIGHT INTO ACTION</div><h2>${staff()?'Better support starts<br>with better understanding.':'Your next chapter<br>starts with a small step.'}</h2><p>${staff()?`${attention?`${attention} learner${attention>1?'s could':' could'} use a little extra support.`:'Your learners are building momentum.'} Explore the signals. Make a meaningful difference.`:'See what’s going well, find what needs practice, and follow a path built around you.'}</p><a class="btn lime" href="#${staff()?'students':'plans'}">${staff()?'Explore student insights':'View my study plan'} ${icon('arrow',13)}</a></div>${art}</section><div class="stats">${stat(staff()?'Enrolled students':'Assessments taken',staff()?learners.length:d.attempts.length,staff()?'In this subject & section':'Your saved assessment history','users')}${stat('Average assessment score',fmt(score)+(score!=null?'%':''),score!=null?'<b>Topic-level performance</b> · evaluated work':'Awaiting evaluated assessments','chart')}${stat('Classroom attendance',fmt(att)+(att!=null?'%':''),'<b>Present + late</b> · recorded sessions','calendar')}${stat(staff()?'Students needing attention':'Study focus areas',staff()?attention:d.performance.topics.filter(t=>t.percent<50).length,staff()?'Score below 40% or attendance below 60%':'Topics with a score below 50%','flag')}</div><div class="grid">${panel(staff()?'Learning & participation':'My learning snapshot','Assessment scores alongside classroom attendance',learners.some(s=>s.average_score!=null||s.attendance_percent!=null)?chart(learners)+`<div class="chart-caption"><span>Showing ${Math.min(learners.length,8)} learner${learners.length===1?'':'s'} · ${E(subject()?.subject_name)}</span><span>Based on recorded activity</span></div>`:empty('A fresh start','Complete an assessment to see learning insights.'),'<div class="legend"><span><i></i>Score</span><span><i class="light"></i>Attendance</span></div>')}${panel('A little support goes a long way','Early signals, before they become bigger gaps',`<div class="risk-content"><div class="donut" style="--value:${learners.length?attention/learners.length*100:0}"><div class="donut-text"><strong>${learners.length}</strong><small>${staff()?'learners':'learner'}</small></div></div><div class="risk-legend"><div><i class="safe"></i>On track<b>${learners.length-attention}</b></div><div><i></i>Needs attention<b>${attention}</b></div></div></div><div class="insight-note">${icon('spark',15)}<span>${attention?'A focused study plan can help turn these signals into progress.':'Keep the momentum going with consistent practice.'} Indicators support a conversation; they are not a final judgment.</span></div>`)}</div><div class="grid">${staff()?`<section class="panel"><div class="panel-head"><div><h2>Every learner, in focus</h2><p>A closer look at performance and participation</p></div><a class="panel-link" href="#students">View all ${icon('arrow',12)}</a></div><div class="spacer"></div>${table(['Student','Avg. score','Attendance','Learning status',''],studentRows(learners))}</section>`:panel('Your topic strengths','A clearer picture of what to practice next',topicBars(d.performance.topics))}${panel('Assessments in motion','A little practice, a little more confidence',latest.length?latest.map(t=>`<div class="list-card"><span class="list-icon">${icon('test',19)}</span><div><h3>${E(t.title)}</h3><p>${t.duration_minutes||'—'} minutes · ${t.max_attempts} attempt${t.max_attempts===1?'':'s'}</p></div><div class="end">${badge(t.status,t.status==='PUBLISHED'?'green':'')}<p><a class="panel-link" href="#tests">View assessment →</a></p></div></div>`).join(''):empty('No assessments yet'),'<a class="panel-link" href="#tests">View all →</a>')}</div><div class="grid equal">${panel('Coursework ahead','Keep the next deadline in sight',items.length?items.map(a=>`<div class="list-card"><span class="list-icon">${icon('folder',18)}</span><div><h3>${E(a.title)}</h3><p>Due ${date(a.due_at)} · ${fmt(a.max_marks)} marks</p></div><a href="#assignments" class="panel-link" style="margin-left:auto">Open →</a></div>`).join(''):empty('A clear coursework list'),'<a class="panel-link" href="#assignments">View all →</a>')}${panel('The next best step','Learning is a journey. Make it your own.',`<div class="callout" style="margin:0"><div class="eyebrow">PERSONALIZED PRACTICE</div><h3 style="margin-top:12px">Focus your effort where it matters.</h3><p>Prioritize weaker topics, build a daily practice rhythm, and check off progress as you go.</p><a href="#plans" class="btn" style="margin-top:16px">Explore study plans ${icon('arrow',13)}</a></div>`)}</div>`}
function topicBars(topics){return topics.length?topics.map(t=>`<div class="list-card"><div style="flex:1"><h3>${E(t.topic_name)}</h3><div class="track" style="width:100%;margin-top:12px;height:6px"><span style="width:${t.percent}%"></span></div></div><strong style="font-size:12px;margin-left:15px">${fmt(t.percent)}%</strong></div>`).join(''):empty('No evaluated topic data yet','Scores appear after an assessment has been fully evaluated.')}
function students(){if(!staff())throw Error('This view is for faculty and academic leaders.');$('#view').innerHTML=`<div class="page-tools"><input class="search" id="student-search" placeholder="Search students…" aria-label="Search students"><div class="filter-tabs"><button data-filter="all" class="active">All learners</button><button data-filter="attention">Needs attention</button></div></div><section class="panel" id="students-table"></section>`;const draw=()=>{const term=$('#student-search').value.toLowerCase();const list=state.data.dashboard.students.filter(s=>s.full_name.toLowerCase().includes(term)&&(state.filter!=='attention'||s.needs_attention));$('#students-table').innerHTML=table(['Student','Avg. score','Attendance','Learning status',''],studentRows(list))};$('#student-search').oninput=draw;$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));draw()});draw()}
async function studentDetail(id){const m=await api(`/students/${id}/performance?subject_id=${state.subject}`);const s=state.data.dashboard?.students.find(s=>s.student_id===id);modal(s?.full_name||'Student learning insights',`<div class="stats" style="grid-template-columns:1fr 1fr">${stat('Assessment score',fmt(m.average_score)+(m.average_score!=null?'%':''),'Evaluated assessments')}${stat('Attendance',fmt(m.attendance_percent)+(m.attendance_percent!=null?'%':''),`${m.recorded_sessions} recorded sessions`,'calendar')}</div><h3>Topic-level progress</h3>${topicBars(m.topics)}<div class="form-actions">${btn(icon('spark',14)+' Generate risk indicator','risk','',`data-id="${id}"`)}${btn('Build a study plan','create-plan','primary',`data-id="${id}"`)}</div>`)}
function tests(){const list=state.data.tests;$('#view').innerHTML=`<div class="info-box">${staff()?'Create an assessment from approved questions, publish it, then review results and descriptive answers here.':'Choose an open assessment. Objective questions are scored automatically; descriptive answers are reviewed by faculty.'}</div><div class="cards">${list.map(t=>{const attempts=state.data.attempts.filter(a=>a.test_id===t.test_id);return `<article class="item-card">${badge(t.status,t.status==='PUBLISHED'?'green':'')}<h3>${E(t.title)}</h3><p>${E(t.description||'A chance to put your understanding into practice.')}</p><div class="meta-row"><span>${icon('clock',13)} ${t.duration_minutes||'—'} min</span><span>${icon('test',13)} ${t.max_attempts} attempt${t.max_attempts===1?'':'s'}</span></div><div class="meta-row">${t.end_at?`Closes ${date(t.end_at)}`:'No scheduled closing date'}</div><div class="actions">${staff()?`${btn('View paper','paper','',`data-id="${t.test_id}"`)}${t.status==='DRAFT'?btn('Publish','publish','primary',`data-id="${t.test_id}"`):t.status==='PUBLISHED'?btn('Close assessment','close-test','small',`data-id="${t.test_id}"`):''}`:`${attempts.some(a=>a.status==='IN_PROGRESS')?btn('Resume assessment','start-attempt','primary',`data-id="${t.test_id}"`):attempts.length<t.max_attempts?btn('Start assessment','start-attempt','primary',`data-id="${t.test_id}"`):badge('Attempts completed','green')}`}</div></article>`}).join('')}</div>${!list.length?empty('No assessments in this view','Faculty can create an assessment using the approved question bank.'):''}<div class="spacer"></div>${panel(staff()?'Assessment activity':'My results','Saved attempts and evaluation status',table(['Learner','Assessment','Score','Status',''],state.data.attempts.map(a=>[E(a.full_name),E(a.title),a.score==null?'—':`${fmt(a.score)} marks`,badge(a.status,a.status==='EVALUATED'?'green':a.status==='SUBMITTED'?'orange':''),`<button class="text-btn" data-action="attempt-result" data-id="${a.attempt_id}">${staff()&&a.status==='SUBMITTED'?'Review answers':'View result'} →</button>`])))}`}
async function paper(id){const qs=await api(`/tests/${id}/questions`);modal('Assessment paper',qs.map((q,i)=>`<section class="question-item"><div class="meta-row">QUESTION ${i+1} · ${fmt(q.marks)} MARKS ${badge(q.question_type)}</div><h3>${E(q.question_text)}</h3>${q.choice_options.map(o=>`<p class="small">${E(o)}</p>`).join('')}${staff()?`<div class="info-box" style="margin:12px 0 0">Answer: ${E(q.correct_answer||'Faculty review')}<br>${E(q.explanation||'')}</div>`:''}</section>`).join(''))}
async function begin(id){const a=await api(`/tests/${id}/attempts`,'POST');state.attempt={...a,test:state.data.tests.find(t=>t.test_id===id)};location.hash='assessment';if(state.page==='assessment')await assessment()}
async function assessment(){if(!state.attempt){location.hash='tests';return}const a=state.attempt;const qs=await api(`/tests/${a.test_id}/questions`);const saved=JSON.parse(sessionStorage.getItem(`learnpath.answers.${a.attempt_id}`)||'{}');$('#view').innerHTML=`<div class="assessment-layout"><section class="panel"><div class="panel-head"><div><h2>${E(a.test?.title||'Assessment')}</h2><p>Your answers are saved in this browser until you submit.</p></div></div><div class="panel-body"><form id="assessment-form">${qs.map((q,i)=>`<section class="question-item" id="question-${i}"><div class="meta-row">QUESTION ${i+1} · ${fmt(q.marks)} MARKS</div><h3>${E(q.question_text)}</h3>${['MCQ','TRUE_FALSE'].includes(q.question_type)?q.choice_options.map((o,k)=>`<label class="answer-option"><input type="radio" name="q_${q.question_id}" value="${E(o)}" ${saved[q.question_id]===o?'checked':''}>${E(o)}</label>`).join(''):`<label class="field"><span class="small muted">Your response</span><textarea name="q_${q.question_id}" maxlength="20000" placeholder="Explain your understanding…">${E(saved[q.question_id]||'')}</textarea></label>`}</section>`).join('')}<div class="form-actions"><button type="submit" class="btn primary">Submit assessment ${icon('check',15)}</button></div></form></div></section><aside class="panel assessment-side"><div class="panel-body"><div><div class="eyebrow">TIME REMAINING</div><div id="timer" class="timer" style="margin-top:10px">Calculating…</div></div><div><p class="small muted" style="margin-top:20px">Your questions</p><div class="number-grid">${qs.map((q,i)=>`<a href="#question-${i}" class="question-number ${saved[q.question_id]?'answered':''}" data-question-link="${i}" data-qid="${q.question_id}">${i+1}</a>`).join('')}</div></div></div></aside></div>`;$$('[data-question-link]').forEach(b=>b.onclick=e=>{e.preventDefault();$(`#question-${b.dataset.questionLink}`).scrollIntoView({behavior:'smooth'})});const f=$('#assessment-form');f.oninput=()=>{const data=Object.fromEntries([...new FormData(f)].map(([k,v])=>[k.slice(2),v]));sessionStorage.setItem(`learnpath.answers.${a.attempt_id}`,JSON.stringify(data));$$('[data-qid]').forEach(b=>b.classList.toggle('answered',!!data[b.dataset.qid]))};f.onsubmit=e=>{e.preventDefault();if(!confirm('Submit your assessment? You cannot change answers after submission.'))return;action(async()=>{const data=new FormData(f);const result=await api(`/attempts/${a.attempt_id}/submit`,'POST',{answers:qs.map(q=>({question_id:q.question_id,answer_text:String(data.get('q_'+q.question_id)||'')}))});sessionStorage.removeItem(`learnpath.answers.${a.attempt_id}`);state.attempt=null;clearInterval(state.timer);toast(result.status==='EVALUATED'?`Assessment submitted. You earned ${fmt(result.score)} marks.`:'Assessment submitted for faculty review.');location.hash='tests'},$('button[type=submit]',f))};const deadline=new Date(a.started_at+'Z').getTime()+Number(a.test?.duration_minutes||30)*60000;const tick=()=>{const left=Math.max(0,Math.floor((deadline-Date.now())/1000));const t=$('#timer');if(!t){clearInterval(state.timer);return}t.textContent=`${Math.floor(left/60).toString().padStart(2,'0')}:${(left%60).toString().padStart(2,'0')}`;if(left===0){$('button[type=submit]',f).disabled=true;t.textContent='Time expired';clearInterval(state.timer)}};tick();state.timer=setInterval(tick,1000)}
async function result(id){const a=await api(`/attempts/${id}`);let qs=[];if(staff())qs=await api(`/tests/${a.test_id}/questions`);modal(staff()?'Assessment review':'Your assessment result',`<div class="results-summary"><div><div class="eyebrow">SCORE EARNED</div><div class="result-score">${fmt(a.score)} <span class="max-mark">marks</span></div></div>${badge(a.status,a.status==='EVALUATED'?'green':'orange')}</div><p class="small muted">Submitted ${date(a.submitted_at)}${a.status==='SUBMITTED'?' · Waiting for faculty evaluation':''}</p>${a.answers.map((ans,i)=>{const q=qs.find(q=>q.question_id===ans.question_id);return `<section class="question-item"><div class="meta-row">RESPONSE ${i+1} ${badge(ans.awarded_marks==null?'Awaiting review':`${fmt(ans.awarded_marks)} marks`,ans.awarded_marks==null?'orange':'green')}</div><h3>${E(q?.question_text||'Your submitted answer')}</h3><p class="small">${E(ans.answer_text||'No answer submitted')}</p>${ans.feedback?`<div class="callout"><strong class="small">Faculty feedback</strong><p>${E(ans.feedback)}</p></div>`:''}${staff()?`<div class="actions" style="margin-top:14px">${btn('Grade response','grade-answer','small',`data-id="${ans.answer_id}" data-max="${q?.marks||100}"`)}${btn(icon('spark',12)+' Suggest feedback','answer-feedback','small',`data-id="${ans.answer_id}"`)}</div>`:''}</section>`}).join('')}`)}
function questions(){let list=state.data.questions;if(!staff())throw Error('Question bank is available to staff.');$('#view').innerHTML=`<div class="page-tools"><div class="filter-tabs">${['all','APPROVED','PENDING_REVIEW'].map((x,i)=>`<button class="${state.filter===x||i===0&&state.filter==='attention'?'active':''}" data-qfilter="${x}">${x==='all'?'All questions':x==='APPROVED'?'Approved':'Needs review'}</button>`).join('')}</div>${btn(icon('spark',14)+' Generate questions','generate-questions')}</div><section class="panel" id="question-table"></section>`;const draw=()=>{$('#question-table').innerHTML=table(['Question','Topic','Difficulty','Source','Review',''],list.filter(q=>!['APPROVED','PENDING_REVIEW'].includes(state.filter)||q.review_status===state.filter).map(q=>[`${E(q.question_text)}<div class="small muted" style="margin-top:5px">${E(q.question_type.replaceAll('_',' '))}</div>`,E(state.ctx.topics.find(t=>t.topic_id===q.topic_id)?.topic_name),badge(q.difficulty,q.difficulty==='HARD'?'orange':''),badge(q.question_source==='GENAI'?'AI generated':'Faculty',q.question_source==='GENAI'?'blue':''),badge(q.review_status,q.review_status==='APPROVED'?'green':'orange'),`<div class="actions">${btn('Edit','edit-question','small',`data-id="${q.question_id}"`)}${q.review_status!=='APPROVED'?btn('Approve','approve-question','small',`data-id="${q.question_id}"`):''}${q.review_status==='PENDING_REVIEW'?btn('Reject','reject-question','small danger',`data-id="${q.question_id}"`):''}</div>`]))};$$('[data-qfilter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.qfilter;$$('[data-qfilter]').forEach(x=>x.classList.toggle('active',x===b));draw()});draw()}
function questionForm(q){const editing=!!q;q=q||{};modal(editing?'Edit question':'Add a thoughtful question',`<div class="form-grid">${selectField('Topic','topic_id',topicOptions())}${selectField('Question type','question_type',['MCQ','TRUE_FALSE','SHORT_ANSWER','DESCRIPTIVE'].map(x=>option(x,x.replaceAll('_',' '),x===q.question_type)).join(''))}${area('Question','question_text',q.question_text,'required maxlength="12000"')}${selectField('Difficulty','difficulty',['EASY','MEDIUM','HARD'].map(x=>option(x,x,x===(q.difficulty||'MEDIUM'))).join(''))}${field('Correct answer','correct_answer','text',q.correct_answer||'')}${area('Answer options · one per line','choice_options',(q.choice_options||[]).join('\n'))}${area('Explanation / reference answer','explanation',q.explanation||'')}<p class="small muted full">For MCQ or true/false questions, the correct answer must exactly match one option. Published assessment questions cannot be edited.</p></div>`,async f=>{const data={topic_id:Number(f.get('topic_id')),question_text:f.get('question_text'),question_type:f.get('question_type'),difficulty:f.get('difficulty'),choice_options:String(f.get('choice_options')).split('\n').map(x=>x.trim()).filter(Boolean),correct_answer:f.get('correct_answer')||null,explanation:f.get('explanation')||null};await api('/questions'+(editing?'/'+q.question_id:''),editing?'PUT':'POST',data);toast(editing?'Question updated.':'Question added to the bank.');await navigate()},editing?'Save question':'Add question');if(q.topic_id)$('[name=topic_id]',$('#modal')).value=q.topic_id}
async function createTest(){const qs=await api(`/questions?subject_id=${state.subject}&limit=200`);const available=qs.filter(q=>q.review_status==='APPROVED'&&q.is_active);if(!available.length)throw Error('Add or approve questions in the question bank first.');modal('Create an assessment',`<div class="form-grid">${field('Assessment title','title','text','','required maxlength="160"')}${field('Duration (minutes)','duration_minutes','number',30,'required min="1" max="300"')}${field('Allowed attempts','max_attempts','number',1,'required min="1" max="10"')}${field('Marks per question','marks','number',2,'required min="0.01" max="1000" step="0.01"')}${area('Description','description')}<div class="full"><label class="field">Choose approved questions</label>${available.map(q=>`<label class="row-check"><input type="checkbox" name="question_ids" value="${q.question_id}"><span>${E(q.question_text)}<small>${E(q.difficulty)} · ${E(q.question_type)}</small></span></label>`).join('')}</div></div>`,async f=>{const ids=f.getAll('question_ids').map(Number);if(!ids.length)throw Error('Choose at least one question.');await api('/tests','POST',{subject_id:state.subject,section_id:state.section,title:f.get('title'),duration_minutes:Number(f.get('duration_minutes')),max_attempts:Number(f.get('max_attempts')),description:f.get('description'),questions:ids.map(id=>({question_id:id,marks:Number(f.get('marks'))}))});toast('Assessment saved as a draft. Publish it when you’re ready.');await navigate()},'Save assessment')}
function assignments(){const list=state.data.assignments;$('#view').innerHTML=`<div class="cards">${list.map(a=>`<article class="item-card">${badge(new Date(a.due_at+'Z')<new Date()?'Deadline passed':'Open for submissions',new Date(a.due_at+'Z')<new Date()?'orange':'green')}<h3>${E(a.title)}</h3><p>${E(a.description||'Put your learning into practice.')}</p><div class="meta-row"><span>${icon('calendar',13)} ${date(a.due_at)}</span><span>${fmt(a.max_marks)} marks</span></div><div class="actions">${staff()?btn('Review submissions','view-submissions','primary',`data-id="${a.assignment_id}"`):state.data.submissions?.[a.assignment_id]?`${badge(state.data.submissions[a.assignment_id].status,state.data.submissions[a.assignment_id].status==='GRADED'?'green':'blue')}${btn('View submission','view-submissions','',`data-id="${a.assignment_id}"`)}`:`${new Date(a.due_at+'Z')>=new Date()?btn('Submit coursework','submit-assignment','primary',`data-id="${a.assignment_id}"`):badge('Submissions closed','orange')}`}</div></article>`).join('')}</div>${!list.length?empty('No assignments yet','Your next coursework task will appear here.'):''}`}
function createAssignment(){modal('Create coursework',`<div class="form-grid">${field('Assignment title','title','text','','required maxlength="160"')}${field('Maximum marks','max_marks','number',100,'required min="1" max="10000"')}${field('Due date & time (your local time)','due_at','datetime-local','','required')}${area('Instructions','description','','required')}</div>`,async f=>{await api('/assignments','POST',{subject_id:state.subject,section_id:state.section,title:f.get('title'),max_marks:Number(f.get('max_marks')),due_at:new Date(f.get('due_at')).toISOString().slice(0,-1),description:f.get('description')});toast('Assignment created.');await navigate()},'Create assignment')}
function submitAssignment(id){const a=state.data.assignments.find(a=>a.assignment_id===id);modal('Submit coursework',`<h3>${E(a.title)}</h3><p class="small muted" style="margin:9px 0 20px">${E(a.description)}</p>${area('Your response','answer_text','','required maxlength="30000"')}<p class="small muted" style="margin-top:15px">One submission is allowed. Review your answer before sending.</p>`,async f=>{await api(`/assignments/${id}/submit`,'POST',{answer_text:f.get('answer_text')});toast('Coursework submitted.');await navigate()},'Submit coursework')}
async function submissions(id){const a=state.data.assignments.find(a=>a.assignment_id===id);const list=await api(`/assignments/${id}/submissions`);modal(a.title,list.length?list.map(s=>`<section class="question-item">${staff()?person(state.data.dashboard?.students.find(u=>u.student_id===s.student_id)?.full_name||'Enrolled student'):''}<div class="actions" style="margin-top:12px">${badge(s.status,s.status==='GRADED'?'green':'orange')}<span class="small muted">${date(s.submitted_at)}</span></div><p class="small" style="margin-top:12px;white-space:pre-wrap">${E(s.answer_text)}</p>${s.marks_awarded!=null?`<h3 style="margin-top:14px">${fmt(s.marks_awarded)} / ${fmt(a.max_marks)} marks</h3><p class="small muted">${E(s.feedback)}</p>`:''}${staff()?btn('Grade submission','grade-submission','small',`data-id="${s.submission_id}" data-max="${a.max_marks}"`):''}</section>`).join(''):empty('No submissions yet','Submitted coursework will appear here.'))}
function grade(id,max,kind){modal(kind==='answer'?'Evaluate response':'Evaluate coursework',`<div class="info-box">Assign a final grade after reviewing the answer. Maximum: ${fmt(max)} marks.</div><div class="form-grid">${field('Marks awarded','marks','number','','required min="0" max="'+max+'" step="0.01"')}${area('Constructive feedback','feedback')}</div>`,async f=>{await api(`/${kind==='answer'?'answers':'submissions'}/${id}/grade`,'PATCH',{marks:Number(f.get('marks')),feedback:f.get('feedback')});toast('Grade and feedback saved.');await navigate()},'Save evaluation')}
function attendance(){const records=state.data.attendance;$('#view').innerHTML=`${staff()?panel('Record a class session','Attendance is linked to this subject and section.',`<form id="attendance-form"><div class="form-grid">${field('Class date','session_date','date',new Date().toISOString().slice(0,10),'required')}${field('Start time','starts_at','time','10:00','required')}${selectField('Topic','topic_id',option('','No specific topic')+topicOptions())}</div><div class="spacer"></div>${table(['Student','Attendance'],state.data.dashboard.students.map(s=>[person(s.full_name),`<select name="student_${s.student_id}" aria-label="Attendance for ${E(s.full_name)}" style="padding:8px;border:1px solid var(--line);border-radius:5px">${['PRESENT','ABSENT','LATE','LEAVE'].map(x=>option(x,x)).join('')}</select>`]))}<div class="form-actions"><button class="btn primary" type="submit">${icon('check',14)} Save attendance</button></div></form>`):''}<div class="spacer"></div>${panel('Attendance history','Recorded classroom participation',table(['Date','Time','Student','Status'],records.map(r=>[date(r.session_date),E(r.starts_at||'—'),E(r.full_name),badge(r.status,['PRESENT','LATE'].includes(r.status)?'green':'orange')])))}`;if(staff())$('#attendance-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);action(async()=>{const records=state.data.dashboard.students.map(s=>({student_id:s.student_id,status:f.get(`student_${s.student_id}`)}));if(!records.length)throw Error('This section has no enrolled students.');await api('/attendance','POST',{subject_id:state.subject,section_id:state.section,topic_id:f.get('topic_id')?Number(f.get('topic_id')):null,session_date:f.get('session_date'),starts_at:f.get('starts_at'),records});toast('Class attendance recorded.');await navigate()},$('button[type=submit]',e.currentTarget))}}
async function plans(){const students=staff()?state.data.dashboard.students:[{student_id:state.user.user_id,full_name:state.user.full_name}];if(!students.length){$('#view').innerHTML=empty('No enrolled students','Enroll students before creating personalized study plans.');return}$('#view').innerHTML=`<div class="page-tools"><label class="field" style="min-width:220px">Learner<select id="plan-student">${students.map(s=>option(s.student_id,s.full_name)).join('')}</select></label><span class="small muted">Personalized topic prioritization · rule-based</span></div><div id="plans-list"></div>`;const draw=async()=>{const id=Number($('#plan-student').value);const plans=await api(`/study-plans?student_id=${id}&subject_id=${state.subject}`);if(!$('#plans-list'))return;$('#plans-list').innerHTML=plans.length?plans.map(p=>{const done=p.items.filter(i=>i.status==='COMPLETED').length;return `<section class="panel" style="margin-bottom:20px"><div class="panel-head"><div><h2>${E(p.title)}</h2><p>${date(p.start_date)} – ${date(p.end_date)} · ${done} of ${p.items.length} steps completed</p></div>${badge(p.status,p.status==='COMPLETED'?'green':'blue')}</div><div class="panel-body"><div class="track" style="width:100%;height:6px;margin-bottom:12px"><span style="width:${p.items.length?done/p.items.length*100:0}%"></span></div>${p.items.map(i=>`<div class="task"><input type="checkbox" class="task-check" data-plan-item="${i.plan_item_id}" ${i.status==='COMPLETED'?'checked':''} aria-label="Mark ${E(state.ctx.topics.find(t=>t.topic_id===i.topic_id)?.topic_name||'task')} complete"><div><h3>${E(state.ctx.topics.find(t=>t.topic_id===i.topic_id)?.topic_name||'Practice topic')}</h3><p>${E(i.recommendation)}</p><div class="meta-row"><span>${icon('calendar',12)} ${date(i.scheduled_date)}</span><span>${icon('clock',12)} ${i.estimated_minutes||30} min</span></div></div></div>`).join('')}</div></section>`}).join(''):empty('A plan is a good place to start','Generate a study plan based on this learner’s topic performance.',btn('Build a study plan','create-plan','primary',`data-id="${id}"`));$$('[data-plan-item]').forEach(box=>box.onchange=()=>action(async()=>{try{await api(`/study-plan-items/${box.dataset.planItem}`,'PATCH',{status:box.checked?'COMPLETED':'PENDING'});toast('Study progress saved.');await draw()}catch(e){box.checked=!box.checked;throw e}},box))};$('#plan-student').onchange=()=>action(draw);await draw()}
function createPlan(id){modal('A plan built around the learner',`<div class="info-box">Topics with lower scores or no assessment history are prioritized. This local recommendation engine uses transparent rules and does not require an LLM key.</div><div class="form-grid">${selectField('Learner','student_id',studentOptions())}${field('Plan length (days)','days','number',7,'required min="1" max="30"')}</div>`,async f=>{await api('/study-plans','POST',{student_id:Number(f.get('student_id')),subject_id:state.subject,days:Number(f.get('days'))});toast('Personalized study plan created.');if(state.page==='plans')await navigate();else location.hash='plans'},'Build study plan');if(id)$('[name=student_id]',$('#modal')).value=id}
function coach(){$('#view').innerHTML=`<div class="grid equal">${panel('Let’s make it click.','An explanation, a worked example, and a little practice.',`<form id="coach-form"><div class="form-grid">${selectField('What are you studying?','topic_id',topicOptions())}${selectField('Explanation language','language',option('English','English')+option('Telugu','తెలుగు · Telugu'))}${area('What would you like to understand?','question','','required maxlength="3000" placeholder="For example: Why is a binary search tree useful?"')}</div><div class="form-actions"><button class="btn primary" type="submit">${icon('spark',14)} Explain this concept</button></div></form>`)}${panel('Your thinking partner','Helpful guidance, with space to think for yourself.',`<div id="coach-output">${empty('A little clarity is on its way','Choose a topic and ask a question. Your explanation will appear here.')}<div class="info-box">AI explanations use the configured LLM provider. If no provider key is set, the app will let you know. Always check important answers with your course material.</div></div>`)}</div>`;$('#coach-form').onsubmit=e=>{e.preventDefault();action(async()=>{const f=new FormData(e.currentTarget);$('#coach-output').innerHTML='<p class="loading"><span class="spinner"></span>Thinking through your question…</p>';try{const data=await api('/ai/doubts','POST',{topic_id:Number(f.get('topic_id')),question:f.get('question'),language:f.get('language')});$('#coach-output').innerHTML=`<div class="chat-output">${Object.entries(data).map(([k,v])=>`<section><h3>${E(k[0].toUpperCase()+k.slice(1))}</h3><p>${E(v)}</p></section>`).join('')}</div>`}catch(err){$('#coach-output').innerHTML=`<div class="info-box">${E(err.message)}</div><p class="small muted">Your assessment, attendance and study-plan workflows still work without a provider key.</p>`}},$('button[type=submit]',e.currentTarget))}}
function gaps(){const list=state.data.gaps||[];$('#view').innerHTML=`<div class="info-box">Topic averages include evaluated attempts only. An unassessed topic is not counted as a zero. Use these signals to guide teaching and follow-up.</div><div class="cards">${list.map(s=>`<section class="item-card"><div class="list-icon">${icon('chart',20)}</div><h3>${E(s.subject_name)}</h3><p>${s.enrolled_students} enrolled learners</p><div style="width:100%">${s.topics.length?s.topics.map(t=>`<div class="list-card"><div style="flex:1"><h3>${E(t.topic_name)}</h3><p>${t.assessed_students} assessed learners</p><div class="track" style="width:100%;margin-top:8px"><span style="width:${t.average_percent}%"></span></div></div>${badge(fmt(t.average_percent)+'%',t.average_percent<50?'orange':'green')}</div>`).join(''):empty('No evaluated topic data yet')}</div></section>`).join('')}</div>`}
const catalogSpecs={departments:{label:'Department',fields:[['department_name','Department name'],['department_code','Department code']]},courses:{label:'Course',fields:[['department_id','Department','departments'],['course_name','Course name'],['course_code','Course code'],['duration_years','Duration (years)','number']]},sections:{label:'Section',fields:[['course_id','Course','courses'],['academic_year','Academic year'],['section_name','Section name']]},subjects:{label:'Subject',fields:[['course_id','Course','courses'],['subject_name','Subject name'],['subject_code','Subject code'],['semester','Semester','number']]},topics:{label:'Topic',fields:[['subject_id','Subject','subjects'],['topic_name','Topic name'],['description','Description']]}};
const recordName=(type,r)=>r[({departments:'department_name',courses:'course_name',sections:'section_name',subjects:'subject_name',topics:'topic_name'})[type]];
const idName=type=>({departments:'department_id',courses:'course_id',sections:'section_id',subjects:'subject_id',topics:'topic_id'})[type];
function catalog(){if(!staff())throw Error('Academic setup is available to staff.');const tabs=admin()?Object.keys(catalogSpecs):['subjects','topics'];if(!tabs.includes(state.tab))state.tab=tabs[0];const spec=catalogSpecs[state.tab];const list=state.ctx[state.tab];$('#view').innerHTML=`<div class="tab-container">${tabs.map(t=>`<button data-catalog-tab="${t}" class="${t===state.tab?'active':''}">${E(t[0].toUpperCase()+t.slice(1))}</button>`).join('')}${admin()?'<button data-catalog-tab="mapping">Enrollments & teaching</button>':''}</div><div class="page-tools"><p class="small muted">Your academic structure, connected.</p>${btn(icon('plus',13)+' Add '+spec.label.toLowerCase(),'create-catalog','primary')}</div><section class="panel">${table(['Name','Details',''],list.map(r=>[E(recordName(state.tab,r)),E(spec.fields.slice(1).map(([k])=>r[k]).filter(v=>v!=null).join(' · ')),btn('Edit','edit-catalog','small',`data-id="${r[idName(state.tab)]}"`)]))}</section>`;$$('[data-catalog-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.catalogTab==='mapping'){mappings();return}state.tab=b.dataset.catalogTab;catalog()})}
function catalogForm(id){const type=state.tab,spec=catalogSpecs[type],old=id?state.ctx[type].find(r=>r[idName(type)]===id):{};modal(`${id?'Edit':'Add'} ${spec.label.toLowerCase()}`,`<div class="form-grid">${spec.fields.map(([key,label,type])=>Array.isArray(state.ctx[type])?selectField(label,key,state.ctx[type].map(r=>option(r[idName(type)],recordName(type,r),r[idName(type)]===old[key])).join('')):field(label,key,type==='number'?'number':'text',old[key]??(key==='academic_year'?'2026-2027':''),`required ${type==='number'?'min="1"':''}`)).join('')}</div>`,async f=>{const data={};spec.fields.forEach(([key,label,type])=>data[key]=key.endsWith('_id')||type==='number'?Number(f.get(key)):f.get(key));await api(`/${state.tab}${id?'/'+id:''}`,id?'PUT':'POST',data);toast('Academic record saved.');await reloadContext();await navigate()},'Save record')}
async function mappings(){const users=await api('/users?limit=200');modal('Connect learners and faculty',`<div class="info-box">Enroll students into a section, or assign faculty to a subject and section. Account and course departments must match.</div><div class="form-grid">${selectField('Mapping type','mapping_type',option('enrollments','Student enrollment')+option('faculty-assignments','Faculty teaching assignment'))}${selectField('Person','person_id',users.filter(u=>['STUDENT','FACULTY'].includes(u.role)).map(u=>option(u.user_id,`${u.full_name} · ${u.role}`)).join(''))}${selectField('Section','section_id',state.ctx.sections.map(s=>option(s.section_id,`${s.section_name} · ${s.academic_year}`)).join(''))}${selectField('Subject (faculty only)','subject_id',state.ctx.subjects.map(s=>option(s.subject_id,s.subject_name)).join(''))}</div>`,async f=>{const type=f.get('mapping_type'),person=users.find(u=>u.user_id===Number(f.get('person_id')));if(type==='enrollments'&&person?.role!=='STUDENT')throw Error('Choose a student for enrollment.');if(type==='faculty-assignments'&&person?.role!=='FACULTY')throw Error('Choose a faculty member for a teaching assignment.');await api('/'+type,'POST',type==='enrollments'?{student_id:person.user_id,section_id:Number(f.get('section_id'))}:{faculty_id:person.user_id,section_id:Number(f.get('section_id')),subject_id:Number(f.get('subject_id'))});toast('Academic mapping saved.');await reloadContext();await navigate()},'Save mapping')}
function users(){$('#view').innerHTML=`<section class="panel">${table(['Person','Role','Department','Account',''],state.data.users.map(u=>[person(u.full_name,u.email),badge(u.role,u.role==='STUDENT'?'green':'blue'),E(state.ctx.departments.find(d=>d.department_id===u.department_id)?.department_name||'Workspace-wide'),badge(u.is_active?'Active':'Disabled',u.is_active?'green':'orange'),u.user_id!==state.user.user_id?btn(u.is_active?'Disable':'Enable','toggle-user','small',`data-id="${u.user_id}" data-active="${u.is_active?0:1}"`):badge('You')]))}</section>`}
function createUser(){modal('Add someone to the workspace',`<div class="form-grid">${field('Full name','full_name','text','','required maxlength="120"')}${field('Email','email','email','','required')}${field('Temporary password','password','password','','required minlength="12" maxlength="128" autocomplete="new-password"')}${selectField('Role','role',['STUDENT','FACULTY','HOD','ADMIN'].map(r=>option(r,r)).join(''))}${selectField('Department','department_id',option('','Workspace-wide (admin only)')+state.ctx.departments.map(d=>option(d.department_id,d.department_name)).join(''))}${field('Registration number (optional)','registration_number')}</div>`,async f=>{await api('/users','POST',{full_name:f.get('full_name'),email:f.get('email'),password:f.get('password'),role:f.get('role'),department_id:f.get('department_id')?Number(f.get('department_id')):null,registration_number:f.get('registration_number')||null});toast('Account created. Add their enrollment or teaching assignment in Academic setup.');await navigate()},'Create account')}
function calendar(){$('#view').innerHTML=panel('The academic calendar','Important dates, with room to prepare.',table(['Event','Starts','Ends','Details'],state.ctx.academic_events.map(e=>[E(e.title),date(e.starts_on),date(e.ends_on),E(e.description)])))}
function createEvent(){modal('Add an academic event',`<div class="form-grid">${field('Event title','title','text','','required')}${field('Starts','starts_on','date','','required')}${field('Ends','ends_on','date','','required')}${area('Description','description')}</div>`,async f=>{await api('/academic_events','POST',Object.fromEntries(f));toast('Academic event saved.');await reloadContext();await navigate()},'Save event')}
function showcase(){$('#view').innerHTML=`<section class="hero"><div><div class="eyebrow">NEURAL CODE NINJAS / NCN–02</div><h2>From a test score<br>to a better next step.</h2><p>One connected project for students, faculty, academic leaders, and administrators.</p><a href="#overview" class="btn lime">Explore the live workspace ${icon('arrow',14)}</a></div>${art}</section><div class="stats">${stat('Connected roles','04','Student · Faculty · HOD · Admin','users')}${stat('Data foundation','MySQL','Real records, relationships & reporting','folder')}${stat('API foundation','FastAPI','Secure roles & academic scope','shield')}${stat('Learning support','AI + GenAI','Practice plans, explanations & review','spark')}</div><div class="grid equal">${panel('Showcase the connected journey','A suggested walkthrough for your presentation.',`<div class="list-card"><span class="list-icon">01</span><div><h3>Start with the bigger picture</h3><p>Dashboard → student scores, attendance and early attention signals.</p></div><a href="#overview" class="panel-link" style="margin-left:auto">Open →</a></div><div class="list-card"><span class="list-icon">02</span><div><h3>Assess understanding</h3><p>Faculty creates a paper; a student takes it; objective answers are scored.</p></div><a href="#tests" class="panel-link" style="margin-left:auto">Open →</a></div><div class="list-card"><span class="list-icon">03</span><div><h3>Turn insight into practice</h3><p>Build a personalized plan, prioritize weak topics, and complete steps.</p></div><a href="#plans" class="panel-link" style="margin-left:auto">Open →</a></div><div class="list-card"><span class="list-icon">04</span><div><h3>Bring guidance into the workflow</h3><p>Generate reviewable questions, explain concepts, and support faculty feedback.</p></div><a href="#coach" class="panel-link" style="margin-left:auto">Open →</a></div>`)}${panel('Built to connect the dots','A real frontend → API → database workflow.',`<div class="task"><span class="list-icon">${icon('grid')}</span><div><h3>Responsive frontend</h3><p>Accessible HTML, CSS and JavaScript, served by FastAPI. No separate frontend build or Node server needed.</p></div></div><div class="task"><span class="list-icon">${icon('shield')}</span><div><h3>Protected backend</h3><p>JWT sessions, Argon2 password hashes, role permissions and department / section access checks.</p></div></div><div class="task"><span class="list-icon">${icon('folder')}</span><div><h3>Persistent MySQL data</h3><p>Academic records, assessments, grades, attendance and study plans persist across browser sessions.</p></div></div><div class="info-box" style="margin-top:16px">Risk indicators and study-plan priorities use documented rules. GenAI features require an LLM provider key. Showcase records are fictional; displayed metrics come from stored data.</div>`)}</div>`}
async function reloadContext(){state.ctx=await api('/ui/context');const pair=state.ctx.scopes.find(s=>s.subject_id===state.subject&&s.section_id===state.section)||state.ctx.scopes[0];state.subject=pair?.subject_id||0;state.section=pair?.section_id||0}
async function dispatch(name,b){const id=Number(b.dataset.id);switch(name){case'logout':logout();break;case'menu':$('.sidebar').classList.toggle('open');break;case'refresh':await reloadContext();await navigate();toast('Workspace refreshed.');break;case'student-detail':await studentDetail(id);break;case'create-question':questionForm();break;case'edit-question':questionForm(state.data.questions.find(q=>q.question_id===id));break;case'approve-question':case'reject-question':await api(`/questions/${id}/review`,'PATCH',{review_status:name==='approve-question'?'APPROVED':'REJECTED'});toast(name==='approve-question'?'Question approved.':'Question rejected.');await navigate();break;case'create-test':await createTest();break;case'publish':case'close-test':if(name==='close-test'&&!confirm('Close this assessment? Students will no longer be able to submit.'))return;await api(`/tests/${id}/status`,'PATCH',{status:name==='publish'?'PUBLISHED':'CLOSED'});toast(name==='publish'?'Assessment published.':'Assessment closed.');await navigate();break;case'paper':await paper(id);break;case'start-attempt':await begin(id);break;case'attempt-result':await result(id);break;case'grade-answer':case'grade-submission':grade(id,Number(b.dataset.max),name==='grade-answer'?'answer':'submission');break;case'create-assignment':createAssignment();break;case'submit-assignment':submitAssignment(id);break;case'view-submissions':await submissions(id);break;case'create-plan':createPlan(id||Number($('#plan-student')?.value)||undefined);break;case'risk':{const r=await api(`/students/${id}/risk?subject_id=${state.subject}`,'POST');modal('Early-warning indicator',`<div class="eyebrow">RULE-BASED SIGNAL · FACULTY REVIEW</div><div class="result-score">${fmt(r.risk_score)} <span class="max-mark">/ 100 risk</span></div>${badge(r.risk_level||'Insufficient data',r.risk_level==='HIGH'?'orange':'green')}<p class="small muted" style="margin-top:20px">${E(r.explanation||r.reason)}</p>`);break}case'generate-questions':modal('Generate a question draft',`<div class="info-box">Generated questions go into a faculty review queue. Review and approve them before adding them to an assessment. Requires a configured LLM provider.</div><div class="form-grid">${selectField('Topic','topic_id',topicOptions())}${field('Number of questions','count','number',3,'min="1" max="10" required')}${selectField('Difficulty','difficulty',['EASY','MEDIUM','HARD'].map(x=>option(x,x,x==='MEDIUM')).join(''))}</div>`,async f=>{await api('/ai/questions','POST',{topic_id:Number(f.get('topic_id')),count:Number(f.get('count')),difficulty:f.get('difficulty')});toast('Draft questions generated. Faculty review required.');await navigate()},'Generate draft questions');break;case'answer-feedback':{const r=await api(`/ai/answers/${id}/feedback`,'POST');modal('Suggested faculty feedback',`<div class="info-box">AI suggestions support your review. Final grades are assigned by faculty.</div><div class="chat-output">${['feedback','strengths','improvements'].map(k=>`<section><h3>${E(k[0].toUpperCase()+k.slice(1))}</h3><p>${E(r[k])}</p></section>`).join('')}</div>`);break}case'create-catalog':catalogForm();break;case'edit-catalog':catalogForm(id);break;case'create-user':createUser();break;case'toggle-user':if(!confirm(`${b.dataset.active==='1'?'Enable':'Disable'} this account?`))return;await api(`/users/${id}/status`,'PATCH',{is_active:b.dataset.active==='1'});toast('Account status updated.');await navigate();break;case'create-event':createEvent();break;case'export':{const learners=staff()?state.data.dashboard.students:[{...state.data.performance,full_name:state.user.full_name}];const csv=[['Student','Subject','Assessment score (%)','Attendance (%)','Needs attention'],...learners.map(s=>[s.full_name,subject()?.subject_name,s.average_score??'',s.attendance_percent??'',(s.needs_attention||(s.average_score!=null&&s.average_score<40)||(s.attendance_percent!=null&&s.attendance_percent<60))?'Yes':'No'])].map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,match=>"'"+match).replaceAll('"','""')+'"').join(',')).join('\r\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='LearnPath-learning-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Learning report exported.');break}}}
if(state.token)initialize().catch(e=>{logout();toast(e.message,true)});else loginScreen();
